//! Lexer for the `lw-demo` language, generated by [`logos`].
//!
//! [`logos`] derives a fast DFA-based lexer from the annotations on
//! [`TokenKind`]. The public [`lex`] function converts a source string into a
//! flat `Vec<Token>` that the parser consumes.

use logos::Logos;

use lw_cst::TextRange;

// ---------------------------------------------------------------------------
// Token kind
// ---------------------------------------------------------------------------

/// Every kind of token the lexer can produce.
///
/// Variants annotated with `#[token(...)]` match exact strings; variants
/// annotated with `#[regex(...)]` match regular expressions.  The fallback
/// `Error` variant captures any unrecognised input so the lexer never panics.
// `error = ()` enables error recovery: any byte logos cannot match is emitted
// as `Err(())`, which the `lex()` function converts to `TokenKind::Error` so
// the token stream stays lossless.
#[derive(Logos, Debug, Clone, PartialEq, Eq)]
#[logos(error = ())]
pub enum TokenKind {
    // --- keywords ---
    #[token("let")]
    Let,

    #[token("import")]
    Import,

    // --- literals & names ---
    /// An integer literal: one or more ASCII digits.
    #[regex(r"[0-9]+")]
    IntLiteral,

    /// A double-quoted string literal (no escape sequences needed for paths).
    #[regex(r#""[^"\n]*""#)]
    StringLiteral,

    /// An identifier: starts with a letter or `_`, followed by alphanumerics
    /// or `_`.  Keywords are matched first, so they won't fall here.
    #[regex(r"[a-zA-Z_][a-zA-Z0-9_]*")]
    Ident,

    // --- operators ---
    #[token("=")]
    Equals,
    #[token("+")]
    Plus,
    #[token("-")]
    Minus,
    #[token("*")]
    Star,
    #[token("/")]
    Slash,

    // --- trivia ---
    /// One or more newline characters (`\n` or `\r\n`).
    #[regex(r"(\r\n|\n)+")]
    Newline,

    /// One or more non-newline whitespace characters.
    #[regex(r"[^\S\n\r]+")]
    Whitespace,

    /// A `// …` line comment (everything up to, but not including, the newline).
    // `allow_greedy = true` is required because `[^\n\r]*` is an unbounded
    // character-class repetition (equivalent to `.*` without newlines).  logos
    // rejects such patterns by default to guard against accidental whole-input
    // consumption; here the intent is deliberate: a comment must consume
    // everything on the line after `//`.  We exclude `\r` as well as `\n` so
    // that CRLF line endings are handled cleanly.
    #[regex(r"//[^\n\r]*", allow_greedy = true)]
    Comment,

    // --- sentinels ---
    /// Logical end of input (synthesised by [`lex`], never emitted by logos).
    Eof,

    /// Unrecognised input — represented explicitly so the token stream is
    /// lossless; logos emits `Err(())` for any byte not matched above and we
    /// convert it here.
    Error,
}

// ---------------------------------------------------------------------------
// Token struct
// ---------------------------------------------------------------------------

/// A single lexed token carrying its kind and byte-range in the source.
#[derive(Debug, Clone)]
pub struct Token {
    pub kind: TokenKind,
    pub range: TextRange,
}

// ---------------------------------------------------------------------------
// Public entry point
// ---------------------------------------------------------------------------

/// Lex `source` into a flat list of tokens, ending with a single [`TokenKind::Eof`].
///
/// Every byte of `source` is covered by exactly one token — whitespace,
/// comments, and errors are all emitted rather than skipped, so the token
/// stream is lossless.
pub fn lex(source: &str) -> Vec<Token> {
    let mut tokens: Vec<Token> = TokenKind::lexer(source)
        .spanned()
        .map(|(kind, span)| Token {
            kind: kind.unwrap_or(TokenKind::Error),
            range: TextRange::new(span.start as u32, span.end as u32),
        })
        .collect();

    let end = source.len() as u32;
    tokens.push(Token {
        kind: TokenKind::Eof,
        range: TextRange::new(end, end),
    });

    tokens
}

// ---------------------------------------------------------------------------
// Unit tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;

    /// Collect just the token kinds from a lex result (excluding Eof).
    fn kinds(source: &str) -> Vec<TokenKind> {
        lex(source)
            .into_iter()
            .map(|t| t.kind)
            .filter(|k| *k != TokenKind::Eof)
            .collect()
    }

    #[test]
    fn lex_let_binding() {
        let toks = kinds("let x = 1");
        assert_eq!(
            toks,
            vec![
                TokenKind::Let,
                TokenKind::Whitespace,
                TokenKind::Ident,
                TokenKind::Whitespace,
                TokenKind::Equals,
                TokenKind::Whitespace,
                TokenKind::IntLiteral,
            ]
        );
    }

    #[test]
    fn lex_import() {
        let toks = kinds("import \"math.lw\"");
        assert_eq!(
            toks,
            vec![
                TokenKind::Import,
                TokenKind::Whitespace,
                TokenKind::StringLiteral,
            ]
        );
    }

    #[test]
    fn lex_operators() {
        let toks = kinds("+-*/");
        assert_eq!(
            toks,
            vec![
                TokenKind::Plus,
                TokenKind::Minus,
                TokenKind::Star,
                TokenKind::Slash,
            ]
        );
    }

    #[test]
    fn lex_comment_and_newline() {
        let toks = kinds("// hello\nlet x = 1");
        assert_eq!(toks[0], TokenKind::Comment);
        assert_eq!(toks[1], TokenKind::Newline);
        assert_eq!(toks[2], TokenKind::Let);
    }

    #[test]
    fn lex_crlf_comment_does_not_consume_newline() {
        // On Windows, a comment should NOT consume the \r in \r\n.
        let toks = kinds("// hello\r\nlet");
        // Comment should end before \r, then we get a newline, then `let`.
        assert_eq!(toks[0], TokenKind::Comment);
        assert_eq!(toks[1], TokenKind::Newline);
        assert_eq!(toks[2], TokenKind::Let);
    }

    #[test]
    fn lex_every_byte_is_covered() {
        let source = "let x = 1 + 2\n";
        let tokens = lex(source);
        // All tokens except Eof should cover the entire source.
        let covered: u32 = tokens
            .iter()
            .filter(|t| t.kind != TokenKind::Eof)
            .map(|t| t.range.end - t.range.start)
            .sum();
        assert_eq!(covered, source.len() as u32, "lossless token coverage");
    }

    #[test]
    fn lex_unknown_char_produces_error() {
        let toks = kinds("@");
        assert_eq!(toks, vec![TokenKind::Error]);
    }
}
